// ALLOWLISTED DATA ACCESS LAYER
// The agent never writes SQL. It may only name a service from this fixed
// list. Anything else is rejected before the database is touched.
const ALLOWED_SERVICES = [
  'DIAG', 'AC_REPAIR', 'FURNACE_REPAIR', 'AC_INSTALL',
  'FURNACE_INSTALL', 'TUNEUP', 'DUCT_CLEAN', 'EMERGENCY'
];

const raw = String($json.service_code || '').trim().toUpperCase();
const businessId = String($json.business_id || '').trim();

if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(businessId)) {
  throw new Error('business_id must be a valid UUID');
}

if (ALLOWED_SERVICES.indexOf(raw) === -1) {
  // Not an error the caller can exploit - just tell it the valid options.
  return [{ json: {
    allowed: false,
    service_code: null,
    business_id: businessId,
    message: 'UNKNOWN_SERVICE: pick one of ' + ALLOWED_SERVICES.join(', ')
  }}];
}

return [{ json: { allowed: true, service_code: raw, business_id: businessId } }];

const row = $input.first().json;

if (!row || !row.service_name) {
  return [{ json: { answer: 'NO_PRICE: that service is not in this business price book. Say a coordinator will confirm pricing.' } }];
}

return [{ json: {
  answer: row.service_name + ': typically $' + row.price_low + ' to $' + row.price_high
    + ' per ' + row.unit
    + (row.notes ? ' (' + row.notes + ')' : '')
    + '. This is a RANGE ONLY. You must tell the caller the final price is confirmed on site by the technician. Never state a single exact price.'
}}];
